class Solution { struct Node{int next[2]={-1,-1};};vector<Node> trie{{}};void insert(int value){int node=0;for(int bit=30;bit>=0;--bit){int digit=value>>bit&1;if(trie[node].next[digit]<0){trie[node].next[digit]=trie.size();trie.push_back({});}node=trie[node].next[digit];}}int query(int value){int node=0,answer=0;for(int bit=30;bit>=0;--bit){int digit=value>>bit&1,wanted=digit^1;if(trie[node].next[wanted]>=0){answer|=1<<bit;node=trie[node].next[wanted];}else node=trie[node].next[digit];}return answer;}public:vector<int> maximizeXor(vector<int>& nums,vector<vector<int>>& queries){sort(nums.begin(),nums.end());vector<int> order(queries.size()),answer(queries.size());iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int a,int b){return queries[a][1]<queries[b][1];});int inserted=0;for(int index:order){while(inserted<(int)nums.size()&&nums[inserted]<=queries[index][1])insert(nums[inserted++]);answer[index]=inserted?query(queries[index][0]):-1;}return answer;} };
